/*
MODA ESTILO | DATOS SINTETICOS PARA SQL SERVER Y POWER BI
Script de demostración AUTOCONTENIDO: ventas y alquileres de vestimenta formal.
Años transaccionales: 2024-2026 (no hay operaciones futuras posteriores al 15/10/2026).
Horarios comerciales: todas las marcas de tiempo entre 08:00 y 18:00.
IMPORTANTE: Ejecutar únicamente en una instancia de pruebas.
Al volver a ejecutar, este archivo borra/recrea solamente las tablas del
esquema dbo y bi dentro de la base dedicada ModaEstilo_BI_Demo.
NO modifica la base original ModaEstilo_Final.
Datos inventados. Precios y montos en soles peruanos (PEN).
Total de alquiler = suma de detalles SIN penalidades.
Penalidades se cobran por separado (tipoOperacion = 'PENALIDAD').
*/
IF DB_ID(N'ModaEstilo_BI_Demo') IS NULL
    CREATE DATABASE ModaEstilo_BI_Demo;
GO
USE ModaEstilo_BI_Demo;
GO
IF SCHEMA_ID(N'bi') IS NULL EXEC(N'CREATE SCHEMA bi');
GO
-- Eliminar vistas primero para poder reiniciar esta BASE DEMO solamente.
DROP VIEW IF EXISTS bi.FactCobranza;
DROP VIEW IF EXISTS bi.FactPago;
DROP VIEW IF EXISTS bi.FactGasto;
DROP VIEW IF EXISTS bi.FactPenalidad;
DROP VIEW IF EXISTS bi.FactAlquiler;
DROP VIEW IF EXISTS bi.FactVenta;
DROP VIEW IF EXISTS bi.DimArticulo;
DROP VIEW IF EXISTS bi.DimCliente;
DROP VIEW IF EXISTS bi.DimTrabajador;
DROP VIEW IF EXISTS bi.DimCategoria;
DROP VIEW IF EXISTS bi.DimCalendario;
GO
DROP TABLE IF EXISTS dbo.Pago;
DROP TABLE IF EXISTS dbo.Gasto;
DROP TABLE IF EXISTS dbo.Penalidad;
DROP TABLE IF EXISTS dbo.Devolucion;
DROP TABLE IF EXISTS dbo.DetalleAlquiler;
DROP TABLE IF EXISTS dbo.DetalleVenta;
DROP TABLE IF EXISTS dbo.Alquiler;
DROP TABLE IF EXISTS dbo.Venta;
DROP TABLE IF EXISTS dbo.Articulo;
DROP TABLE IF EXISTS dbo.Cliente;
DROP TABLE IF EXISTS dbo.Trabajador;
DROP TABLE IF EXISTS dbo.Categoria;
DROP TABLE IF EXISTS dbo.DimFecha;
GO
SET DATEFORMAT ymd;
GO


CREATE TABLE dbo.Categoria (
 idCategoria INT IDENTITY(1,1) PRIMARY KEY,
 nombreCategoria NVARCHAR(100) NOT NULL UNIQUE,
 descripcion NVARCHAR(250)
);
CREATE TABLE dbo.Trabajador (
 idTrabajador INT IDENTITY(1,1) PRIMARY KEY,
 dni CHAR(8) NOT NULL UNIQUE, nombres NVARCHAR(80) NOT NULL,
 apellidos NVARCHAR(100) NOT NULL, cargo NVARCHAR(60) NOT NULL,
 estado NVARCHAR(20) NOT NULL
);
CREATE TABLE dbo.Cliente (
 idCliente INT IDENTITY(1,1) PRIMARY KEY,
 dni CHAR(8) NOT NULL UNIQUE, nombres NVARCHAR(80) NOT NULL,
 apellidos NVARCHAR(100) NOT NULL, telefono VARCHAR(20),
 correo VARCHAR(100), direccion NVARCHAR(200),distrito NVARCHAR(50),
 fechaRegistro DATETIME2(0) NOT NULL
);
CREATE TABLE dbo.Articulo (
 idArticulo INT IDENTITY(1,1) PRIMARY KEY,
 idCategoria INT NOT NULL REFERENCES dbo.Categoria(idCategoria),
 codigo VARCHAR(30) NOT NULL UNIQUE, nombre NVARCHAR(100) NOT NULL,
 talla NVARCHAR(20), color NVARCHAR(50),
 costoCompra DECIMAL(12,2) NOT NULL CHECK(costoCompra>=0),
 precioAlquiler DECIMAL(12,2) NOT NULL CHECK(precioAlquiler>=0),
 precioVenta DECIMAL(12,2) NOT NULL CHECK(precioVenta>=0),
 stock INT NOT NULL CHECK(stock>=0), stockMinimo INT NOT NULL CHECK(stockMinimo>=0),
 estado NVARCHAR(20) NOT NULL
);
CREATE TABLE dbo.Venta (
 idVenta INT IDENTITY(1,1) PRIMARY KEY,
 idCliente INT NOT NULL REFERENCES dbo.Cliente(idCliente),
 idTrabajador INT NOT NULL REFERENCES dbo.Trabajador(idTrabajador),
 fechaVenta DATETIME2(0) NOT NULL,
 tipoComprobante NVARCHAR(30) NOT NULL,canalVenta NVARCHAR(30) NOT NULL,
 estado NVARCHAR(20) NOT NULL,
 total DECIMAL(12,2) NOT NULL CHECK(total>=0)
);
CREATE TABLE dbo.Alquiler (
 idAlquiler INT IDENTITY(1,1) PRIMARY KEY,
 idCliente INT NOT NULL REFERENCES dbo.Cliente(idCliente),
 idTrabajador INT NOT NULL REFERENCES dbo.Trabajador(idTrabajador),
 fechaAlquiler DATETIME2(0) NOT NULL,
 fechaEntrega DATETIME2(0),
 fechaDevolucionProgramada DATETIME2(0) NOT NULL,
 fechaDevolucionReal DATETIME2(0),
 tipoEvento NVARCHAR(50) NOT NULL,canalReserva NVARCHAR(30) NOT NULL,
 estado NVARCHAR(20) NOT NULL,
 observacion NVARCHAR(250), total DECIMAL(12,2) NOT NULL CHECK(total>=0),
 CONSTRAINT CK_Alquiler_FechaLogica CHECK (
   fechaDevolucionProgramada>=fechaAlquiler
   AND (fechaEntrega IS NULL OR fechaEntrega>=fechaAlquiler)
   AND (fechaEntrega IS NULL OR fechaDevolucionProgramada>=fechaEntrega)
   AND (fechaDevolucionReal IS NULL OR (fechaEntrega IS NOT NULL AND fechaDevolucionReal>=fechaEntrega))
 )
);
CREATE TABLE dbo.DetalleVenta (
 idDetalleVenta INT IDENTITY(1,1) PRIMARY KEY,
 idVenta INT NOT NULL REFERENCES dbo.Venta(idVenta),
 idArticulo INT NOT NULL REFERENCES dbo.Articulo(idArticulo),
 cantidad INT NOT NULL CHECK(cantidad>0),
 precioUnitario DECIMAL(12,2) NOT NULL CHECK(precioUnitario>=0),
 costoUnitario DECIMAL(12,2) NOT NULL CHECK(costoUnitario>=0),
 subtotal DECIMAL(12,2) NOT NULL CHECK(subtotal>=0),
 CONSTRAINT UQ_DetalleVenta_Producto UNIQUE(idVenta,idArticulo),
 CONSTRAINT CK_DetalleVenta_Subtotal CHECK(subtotal=cantidad*precioUnitario)
);
CREATE TABLE dbo.DetalleAlquiler (
 idDetalleAlquiler INT IDENTITY(1,1) PRIMARY KEY,
 idAlquiler INT NOT NULL REFERENCES dbo.Alquiler(idAlquiler),
 idArticulo INT NOT NULL REFERENCES dbo.Articulo(idArticulo),
 cantidad INT NOT NULL CHECK(cantidad>0),
 precioUnitario DECIMAL(12,2) NOT NULL CHECK(precioUnitario>=0),
 subtotal DECIMAL(12,2) NOT NULL CHECK(subtotal>=0),
 CONSTRAINT UQ_DetalleAlquiler_Producto UNIQUE(idAlquiler,idArticulo),
 CONSTRAINT CK_DetalleAlquiler_Subtotal CHECK(subtotal=cantidad*precioUnitario)
);
CREATE TABLE dbo.Devolucion (
 idDevolucion INT IDENTITY(1,1) PRIMARY KEY,
 idAlquiler INT NOT NULL UNIQUE REFERENCES dbo.Alquiler(idAlquiler),
 fechaDevolucion DATETIME2(0) NOT NULL,
 estadoArticulo NVARCHAR(40) NOT NULL,
 observaciones NVARCHAR(250)
);
CREATE TABLE dbo.Penalidad (
 idPenalidad INT IDENTITY(1,1) PRIMARY KEY,
 idDevolucion INT NOT NULL REFERENCES dbo.Devolucion(idDevolucion),
 idArticulo INT NULL REFERENCES dbo.Articulo(idArticulo),
 tipoPenalidad NVARCHAR(40) NOT NULL,
 descripcion NVARCHAR(250) NOT NULL,
 diasRetraso INT NOT NULL DEFAULT(0) CHECK(diasRetraso>=0),
 monto DECIMAL(12,2) NOT NULL CHECK(monto>0),
 fechaRegistro DATETIME2(0) NOT NULL,
 estadoPenalidad NVARCHAR(20) NOT NULL,
 CONSTRAINT CK_Penalidad_Tipo CHECK (tipoPenalidad IN (N'Mora',N'Limpieza',N'Reparación',N'Reposición')),
 CONSTRAINT CK_Penalidad_Mora CHECK((tipoPenalidad=N'Mora' AND diasRetraso>0 AND idArticulo IS NULL) OR (tipoPenalidad<>N'Mora' AND diasRetraso=0 AND idArticulo IS NOT NULL))
);
CREATE TABLE dbo.Gasto (
 idGasto INT IDENTITY(1,1) PRIMARY KEY,
 fechaGasto DATETIME2(0) NOT NULL, tipoGasto NVARCHAR(50) NOT NULL,
 descripcion NVARCHAR(250) NOT NULL,
 monto DECIMAL(12,2) NOT NULL CHECK(monto>0),
 idVenta INT NULL REFERENCES dbo.Venta(idVenta),
 idAlquiler INT NULL REFERENCES dbo.Alquiler(idAlquiler),
 CONSTRAINT CK_Gasto_UnaRelacion CHECK(idVenta IS NULL OR idAlquiler IS NULL)
);
CREATE TABLE dbo.Pago (
 idPago INT IDENTITY(1,1) PRIMARY KEY,
 tipoOperacion NVARCHAR(20) NOT NULL,
 idVenta INT NULL REFERENCES dbo.Venta(idVenta),
 idAlquiler INT NULL REFERENCES dbo.Alquiler(idAlquiler),
 idPenalidad INT NULL REFERENCES dbo.Penalidad(idPenalidad),
 fechaPago DATETIME2(0) NOT NULL,
 metodoPago NVARCHAR(30) NOT NULL,
 monto DECIMAL(12,2) NOT NULL CHECK(monto>0),
 estadoPago NVARCHAR(20) NOT NULL,
 CONSTRAINT CK_Pago_Origen CHECK (
  (tipoOperacion=N'VENTA' AND idVenta IS NOT NULL AND idAlquiler IS NULL AND idPenalidad IS NULL)
  OR (tipoOperacion=N'ALQUILER' AND idVenta IS NULL AND idAlquiler IS NOT NULL AND idPenalidad IS NULL)
  OR (tipoOperacion=N'PENALIDAD' AND idVenta IS NULL AND idAlquiler IS NULL AND idPenalidad IS NOT NULL)
 )
);
CREATE TABLE dbo.DimFecha (
 FechaKey INT NOT NULL PRIMARY KEY,
 Fecha DATE NOT NULL UNIQUE, Anio INT NOT NULL, Trimestre INT NOT NULL,
 MesNumero INT NOT NULL, MesNombre NVARCHAR(20) NOT NULL,
 AnioMes CHAR(7) NOT NULL, DiaMes INT NOT NULL,
 DiaSemanaNumero INT NOT NULL, DiaSemanaNombre NVARCHAR(15) NOT NULL,
 EsFinSemana BIT NOT NULL
);
GO

