    (N'PENALIDAD', NULL, NULL, 97, '2026-07-31T13:15:00', N'Transferencia', 45.00, N'Confirmado'),
    (N'PENALIDAD', NULL, NULL, 98, '2026-08-07T16:15:00', N'Efectivo', 45.00, N'Confirmado'),
