-- Calendario explícito para el modelo estrella (incluye fechas programadas de fin de 2026).
;WITH N AS (
 SELECT TOP (1096) ROW_NUMBER() OVER(ORDER BY a.object_id,b.object_id)-1 AS n
 FROM sys.all_objects a CROSS JOIN sys.all_objects b
), D AS (
 SELECT DATEADD(DAY,n,CONVERT(date,'20240101',112)) AS fecha FROM N
), F AS (
 SELECT fecha, ((DATEDIFF(DAY,CONVERT(date,'19000101',112),fecha)%7)+1) AS semana FROM D
)
INSERT INTO dbo.DimFecha (FechaKey,Fecha,Anio,Trimestre,MesNumero,MesNombre,AnioMes,DiaMes,DiaSemanaNumero,DiaSemanaNombre,EsFinSemana)
SELECT YEAR(fecha)*10000+MONTH(fecha)*100+DAY(fecha),fecha,YEAR(fecha),DATEPART(QUARTER,fecha),MONTH(fecha),
 CHOOSE(MONTH(fecha),N'Enero',N'Febrero',N'Marzo',N'Abril',N'Mayo',N'Junio',N'Julio',N'Agosto',N'Setiembre',N'Octubre',N'Noviembre',N'Diciembre'),
 CONVERT(CHAR(7),fecha,120),DAY(fecha),semana,
 CHOOSE(semana,N'Lunes',N'Martes',N'Miércoles',N'Jueves',N'Viernes',N'Sábado',N'Domingo'),
 CASE WHEN semana IN (6,7) THEN 1 ELSE 0 END
FROM F WHERE fecha<='2026-12-31';
GO

-- Validaciones financieras (THROW detiene la ejecución si se rompe la coherencia).
IF EXISTS (
 SELECT 1 FROM dbo.Venta v OUTER APPLY (SELECT SUM(d.subtotal) t FROM dbo.DetalleVenta d WHERE d.idVenta=v.idVenta) x
 WHERE ABS(v.total-ISNULL(x.t,0))>0.001
) THROW 51001, 'Total de venta distinto a suma de sus detalles.', 1;
IF EXISTS (
 SELECT 1 FROM dbo.Alquiler a OUTER APPLY (SELECT SUM(d.subtotal) t FROM dbo.DetalleAlquiler d WHERE d.idAlquiler=a.idAlquiler) x
 WHERE ABS(a.total-ISNULL(x.t,0))>0.001
) THROW 51002, 'Total de alquiler distinto a suma de sus detalles.', 1;
IF EXISTS (
 SELECT 1 FROM dbo.Venta v OUTER APPLY (SELECT SUM(p.monto) t FROM dbo.Pago p WHERE p.tipoOperacion=N'VENTA' AND p.idVenta=v.idVenta AND p.estadoPago=N'Confirmado') x
 WHERE ISNULL(x.t,0)>v.total
) THROW 51003, 'Pago de venta mayor al total de venta.', 1;
IF EXISTS (
 SELECT 1 FROM dbo.Alquiler a OUTER APPLY (SELECT SUM(p.monto) t FROM dbo.Pago p WHERE p.tipoOperacion=N'ALQUILER' AND p.idAlquiler=a.idAlquiler AND p.estadoPago=N'Confirmado') x
 WHERE ISNULL(x.t,0)>a.total
) THROW 51004, 'Pago de alquiler mayor al total de alquiler.', 1;
IF EXISTS (
 SELECT 1 FROM dbo.Penalidad e OUTER APPLY (SELECT SUM(p.monto) t FROM dbo.Pago p WHERE p.tipoOperacion=N'PENALIDAD' AND p.idPenalidad=e.idPenalidad AND p.estadoPago=N'Confirmado') x
 WHERE ISNULL(x.t,0)>e.monto
) THROW 51005, 'Pago de penalidad mayor a su monto.', 1;
IF EXISTS (
 SELECT 1 FROM dbo.Alquiler a JOIN dbo.Devolucion d ON a.idAlquiler=d.idAlquiler
 WHERE a.fechaDevolucionReal<>d.fechaDevolucion OR a.estado<>N'Devuelto'
) THROW 51006, 'Devolucion inconsistente con alquiler.', 1;
GO


-- VISTAS BI. Cada tabla de hechos tiene un grano específico; no combinar
-- detalles con pagos/penalidades en una sola consulta para evitar duplicaciones.
CREATE VIEW bi.DimCalendario AS
 SELECT FechaKey,Fecha,Anio,Trimestre,MesNumero,MesNombre,AnioMes,DiaMes,DiaSemanaNumero,DiaSemanaNombre,EsFinSemana
 FROM dbo.DimFecha;
GO
CREATE VIEW bi.DimCategoria AS
 SELECT idCategoria AS CategoriaKey,nombreCategoria AS Categoria,descripcion AS DescripcionCategoria
 FROM dbo.Categoria;
GO
CREATE VIEW bi.DimCliente AS
 SELECT idCliente AS ClienteKey, dni AS DNI,nombres AS Nombres,apellidos AS Apellidos,
 CONCAT(nombres,N' ',apellidos) AS Cliente,telefono AS Telefono,correo AS Correo,
 direccion AS Direccion,distrito AS Distrito,CONVERT(date,fechaRegistro) AS FechaRegistro
 FROM dbo.Cliente;
GO
CREATE VIEW bi.DimTrabajador AS
 SELECT idTrabajador AS TrabajadorKey, CONCAT(nombres,N' ',apellidos) AS Trabajador,
 cargo AS Cargo,estado AS EstadoTrabajador FROM dbo.Trabajador;
GO
CREATE VIEW bi.DimArticulo AS
 SELECT a.idArticulo AS ArticuloKey,a.idCategoria AS CategoriaKey,a.codigo AS Codigo,
 a.nombre AS Articulo,a.talla AS Talla,a.color AS Color,c.nombreCategoria AS Categoria,
 a.precioVenta AS PrecioListaVenta, a.precioAlquiler AS PrecioListaAlquiler,
 a.stock AS StockActual,a.stockMinimo AS StockMinimo,a.estado AS EstadoArticulo
 FROM dbo.Articulo a JOIN dbo.Categoria c ON c.idCategoria=a.idCategoria;
GO
-- GRANO: 1 fila = 1 artículo dentro de una venta.
CREATE VIEW bi.FactVenta AS
 SELECT d.idDetalleVenta AS DetalleVentaKey,v.idVenta AS VentaID,
 v.idCliente AS ClienteKey,v.idTrabajador AS TrabajadorKey,d.idArticulo AS ArticuloKey,
 YEAR(v.fechaVenta)*10000+MONTH(v.fechaVenta)*100+DAY(v.fechaVenta) AS FechaVentaKey,
 v.fechaVenta AS FechaVentaHora,v.tipoComprobante AS Comprobante,v.canalVenta AS CanalVenta,v.estado AS EstadoVenta,
 d.cantidad AS Cantidad,d.precioUnitario AS PrecioUnitario,
 d.subtotal AS ImporteVenta,d.costoUnitario*d.cantidad AS CostoMercaderia,
 d.subtotal-d.costoUnitario*d.cantidad AS MargenBrutoVenta
 FROM dbo.DetalleVenta d JOIN dbo.Venta v ON v.idVenta=d.idVenta;
GO
-- GRANO: 1 fila = 1 artículo dentro de un contrato de alquiler.
-- El importe del contrato (total) no se repite: se usa subtotal del detalle.
CREATE VIEW bi.FactAlquiler AS
 SELECT d.idDetalleAlquiler AS DetalleAlquilerKey,a.idAlquiler AS AlquilerID,
 a.idCliente AS ClienteKey,a.idTrabajador AS TrabajadorKey,d.idArticulo AS ArticuloKey,
 YEAR(a.fechaAlquiler)*10000+MONTH(a.fechaAlquiler)*100+DAY(a.fechaAlquiler) AS FechaAlquilerKey,
 CASE WHEN a.fechaEntrega IS NULL THEN NULL ELSE YEAR(a.fechaEntrega)*10000+MONTH(a.fechaEntrega)*100+DAY(a.fechaEntrega) END AS FechaEntregaKey,
 YEAR(a.fechaDevolucionProgramada)*10000+MONTH(a.fechaDevolucionProgramada)*100+DAY(a.fechaDevolucionProgramada) AS FechaDevolucionProgramadaKey,
 CASE WHEN a.fechaDevolucionReal IS NULL THEN NULL ELSE YEAR(a.fechaDevolucionReal)*10000+MONTH(a.fechaDevolucionReal)*100+DAY(a.fechaDevolucionReal) END AS FechaDevolucionRealKey,
 a.fechaAlquiler AS FechaAlquilerHora,a.fechaEntrega AS FechaEntregaHora,
 a.fechaDevolucionProgramada AS FechaDevolucionProgramadaHora,
 a.fechaDevolucionReal AS FechaDevolucionRealHora,
 a.estado AS EstadoAlquiler,a.tipoEvento AS TipoEvento,a.canalReserva AS CanalReserva,
 d.cantidad AS Cantidad,d.precioUnitario AS PrecioUnitario,
 d.subtotal AS ImporteAlquiler,
 CASE WHEN a.fechaDevolucionReal IS NOT NULL
 THEN CASE WHEN DATEDIFF(DAY,CONVERT(date,a.fechaDevolucionProgramada),CONVERT(date,a.fechaDevolucionReal))>0
 THEN DATEDIFF(DAY,CONVERT(date,a.fechaDevolucionProgramada),CONVERT(date,a.fechaDevolucionReal)) ELSE 0 END
 ELSE NULL END AS DiasRetraso,
 CASE WHEN a.fechaDevolucionReal IS NOT NULL
 THEN CASE WHEN CONVERT(date,a.fechaDevolucionReal)>CONVERT(date,a.fechaDevolucionProgramada) THEN 0 ELSE 1 END
 ELSE NULL END AS FuePuntual
 FROM dbo.DetalleAlquiler d JOIN dbo.Alquiler a ON a.idAlquiler=d.idAlquiler;
GO
-- GRANO: 1 fila = 1 cargo por mora, limpieza, reparación o reposición.
CREATE VIEW bi.FactPenalidad AS
 SELECT p.idPenalidad AS PenalidadID,p.idDevolucion AS DevolucionID,
 de.idAlquiler AS AlquilerID,a.idCliente AS ClienteKey,a.idTrabajador AS TrabajadorKey,
 p.idArticulo AS ArticuloKey,
 YEAR(p.fechaRegistro)*10000+MONTH(p.fechaRegistro)*100+DAY(p.fechaRegistro) AS FechaPenalidadKey,
 p.fechaRegistro AS FechaPenalidadHora,p.tipoPenalidad AS TipoPenalidad,
 p.descripcion AS MotivoPenalidad,p.diasRetraso AS DiasRetrasoPenalidad,
 p.monto AS MontoPenalidad,p.estadoPenalidad AS EstadoPenalidad
 FROM dbo.Penalidad p JOIN dbo.Devolucion de ON de.idDevolucion=p.idDevolucion
 JOIN dbo.Alquiler a ON a.idAlquiler=de.idAlquiler;
GO
-- GRANO: 1 fila = 1 gasto operativo.
CREATE VIEW bi.FactGasto AS
 SELECT idGasto AS GastoID,
 YEAR(fechaGasto)*10000+MONTH(fechaGasto)*100+DAY(fechaGasto) AS FechaGastoKey,
 fechaGasto AS FechaGastoHora,tipoGasto AS TipoGasto,
 descripcion AS DescripcionGasto,monto AS MontoGasto,
 idVenta AS VentaID,idAlquiler AS AlquilerID FROM dbo.Gasto;
GO
-- GRANO: 1 fila = 1 deuda individual (venta, alquiler o penalidad).
-- Permite evaluar saldos sin mezclar las distintas fechas de cobro.
CREATE VIEW bi.FactCobranza AS
WITH C AS (
 SELECT tipoOperacion, idVenta, idAlquiler, idPenalidad, SUM(monto) AS ImporteCobrado
 FROM dbo.Pago WHERE estadoPago=N'Confirmado'
 GROUP BY tipoOperacion,idVenta,idAlquiler,idPenalidad
)
SELECT N'VENTA' AS TipoOperacion, v.idVenta AS OperacionID, v.idCliente AS ClienteKey,
 v.idTrabajador AS TrabajadorKey,
 YEAR(v.fechaVenta)*10000+MONTH(v.fechaVenta)*100+DAY(v.fechaVenta) AS FechaEmisionKey,
 v.total AS ImporteFacturado,ISNULL(c.ImporteCobrado,0) AS ImporteCobrado,
 v.total-ISNULL(c.ImporteCobrado,0) AS SaldoPendiente
FROM dbo.Venta v LEFT JOIN C c ON c.tipoOperacion=N'VENTA' AND c.idVenta=v.idVenta
UNION ALL
SELECT N'ALQUILER',a.idAlquiler,a.idCliente,a.idTrabajador,
 YEAR(a.fechaAlquiler)*10000+MONTH(a.fechaAlquiler)*100+DAY(a.fechaAlquiler),
 a.total,ISNULL(c.ImporteCobrado,0),a.total-ISNULL(c.ImporteCobrado,0)
FROM dbo.Alquiler a LEFT JOIN C c ON c.tipoOperacion=N'ALQUILER' AND c.idAlquiler=a.idAlquiler
UNION ALL
SELECT N'PENALIDAD',pe.idPenalidad,a.idCliente,a.idTrabajador,
 YEAR(pe.fechaRegistro)*10000+MONTH(pe.fechaRegistro)*100+DAY(pe.fechaRegistro),
 pe.monto,ISNULL(c.ImporteCobrado,0),pe.monto-ISNULL(c.ImporteCobrado,0)
FROM dbo.Penalidad pe
JOIN dbo.Devolucion de ON de.idDevolucion=pe.idDevolucion
JOIN dbo.Alquiler a ON a.idAlquiler=de.idAlquiler
LEFT JOIN C c ON c.tipoOperacion=N'PENALIDAD' AND c.idPenalidad=pe.idPenalidad;
GO
-- GRANO: 1 fila = 1 movimiento de cobro (no un ingreso duplicado).
CREATE VIEW bi.FactPago AS
 SELECT p.idPago AS PagoID,
 YEAR(p.fechaPago)*10000+MONTH(p.fechaPago)*100+DAY(p.fechaPago) AS FechaPagoKey,
 p.fechaPago AS FechaPagoHora,p.tipoOperacion AS TipoOperacion,
 p.idVenta AS VentaID,p.idAlquiler AS AlquilerID,p.idPenalidad AS PenalidadID,
 COALESCE(v.idCliente,a.idCliente,ax.idCliente) AS ClienteKey,
 COALESCE(v.idTrabajador,a.idTrabajador,ax.idTrabajador) AS TrabajadorKey,
 p.metodoPago AS MetodoPago,p.monto AS MontoPago,p.estadoPago AS EstadoPago
 FROM dbo.Pago p
 LEFT JOIN dbo.Venta v ON p.idVenta=v.idVenta
 LEFT JOIN dbo.Alquiler a ON p.idAlquiler=a.idAlquiler
 LEFT JOIN dbo.Penalidad pe ON p.idPenalidad=pe.idPenalidad
 LEFT JOIN dbo.Devolucion de ON pe.idDevolucion=de.idDevolucion
 LEFT JOIN dbo.Alquiler ax ON de.idAlquiler=ax.idAlquiler;
GO
-- RECUENTOS Y CONTROL BASICO
SELECT N'Clientes' AS Tabla,COUNT(*) AS Registros FROM dbo.Cliente
UNION ALL SELECT N'Articulos',COUNT(*) FROM dbo.Articulo
UNION ALL SELECT N'Ventas',COUNT(*) FROM dbo.Venta
UNION ALL SELECT N'Detalle ventas',COUNT(*) FROM dbo.DetalleVenta
UNION ALL SELECT N'Alquileres',COUNT(*) FROM dbo.Alquiler
UNION ALL SELECT N'Detalle alquileres',COUNT(*) FROM dbo.DetalleAlquiler
UNION ALL SELECT N'Devoluciones',COUNT(*) FROM dbo.Devolucion
UNION ALL SELECT N'Penalidades',COUNT(*) FROM dbo.Penalidad
UNION ALL SELECT N'Pagos',COUNT(*) FROM dbo.Pago
UNION ALL SELECT N'Gastos',COUNT(*) FROM dbo.Gasto;
GO
